#include <filesystem>

// Template content will be embedded here
#include "templates.h"

const char* VERSION = "1.17.0";
const char* GIT_HASH = "9135bd68ddc9ea65023d967c75048a7a86a5d495";
const char* SQLITE_VERSION = "3.42.0";

void print_help() {
    std::cout << "Doxygen version " << VERSION << " (" << GIT_HASH << ")\n";
    std::cout << "Copyright Dimitri van Heesch 1997-2025\n";
    std::cout << "\n";
    std::cout << "You can use Doxygen in a number of ways:\n";
    std::cout << "\n";
    std::cout << "1) Use Doxygen to generate a template configuration file*:\n";
    std::cout << "    doxygen [-s] -g [configName]\n";
    std::cout << "\n";
    std::cout << "2) Use Doxygen to update an old configuration file*:\n";
    std::cout << "    doxygen [-s] -u [configName]\n";
    std::cout << "\n";
    std::cout << "3) Use Doxygen to generate documentation using an existing configuration file*:\n";
    std::cout << "    doxygen [configName]\n";
    std::cout << "\n";
    std::cout << "4) Use Doxygen to generate a template file controlling the layout of the\n";
    std::cout << "   generated documentation:\n";
    std::cout << "    doxygen -l [layoutFileName]\n";
    std::cout << "\n";
    std::cout << "    In case layoutFileName is omitted DoxygenLayout.xml will be used as filename.\n";
    std::cout << "    If - is used for layoutFileName Doxygen will write to standard output.\n";
    std::cout << "\n";
    std::cout << "5) Use Doxygen to generate a template style sheet file for RTF, HTML or Latex.\n";
    std::cout << "    RTF:        doxygen -w rtf styleSheetFile\n";
    std::cout << "    HTML:       doxygen -w html headerFile footerFile styleSheetFile [configFile]\n";
    std::cout << "    LaTeX:      doxygen -w latex headerFile footerFile styleSheetFile [configFile]\n";
    std::cout << "\n";
    std::cout << "6) Use Doxygen to generate a rtf extensions file\n";
    std::cout << "    doxygen -e rtf extensionsFile\n";
    std::cout << "\n";
    std::cout << "    If - is used for extensionsFile Doxygen will write to standard output.\n";
    std::cout << "\n";
    std::cout << "7) Use Doxygen to compare the used configuration file with the template configuration file\n";
    std::cout << "    doxygen -x [configFile]\n";
    std::cout << "\n";
    std::cout << "   Use Doxygen to compare the used configuration file with the template configuration file\n";
    std::cout << "   without replacing the environment variables or CMake type replacement variables\n";
    std::cout << "    doxygen -x_noenv [configFile]\n";
    std::cout << "\n";
    std::cout << "8) Use Doxygen to show a list of built-in emojis.\n";
    std::cout << "    doxygen -f emoji outputFileName\n";
    std::cout << "\n";
    std::cout << "    If - is used for outputFileName Doxygen will write to standard output.\n";
    std::cout << "\n";
    std::cout << "*) If -s is specified the comments of the configuration items in the config file will be omitted.\n";
    std::cout << "   If configName is omitted 'Doxyfile' will be used as a default.\n";
    std::cout << "   If - is used for configFile Doxygen will write / read the configuration to /from standard output / input.\n";
    std::cout << "\n";
    std::cout << "If -q is used for a Doxygen documentation run, Doxygen will see this as if QUIET=YES has been set.\n";
    std::cout << "\n";
    std::cout << "-v print version string, -V print extended version information\n";
    std::cout << "-h,-? prints usage help information\n";
    std::cout << "doxygen -d prints additional usage flags for debugging purposes\n";
}

void print_version() {
    std::cout << VERSION << " (" << GIT_HASH << ")\n";
}

void print_extended_version() {
    std::cout << VERSION << " (" << GIT_HASH << ")\n";
    std::cout << "    with sqlite3 " << SQLITE_VERSION << ".\n";
}

void print_debug_help() {
    std::cout << "Developer parameters:\n";
    std::cout << "  -m          dump symbol map\n";
    std::cout << "  -b          making messages output unbuffered\n";
    std::cout << "  -c <file>   process input file as a comment block and produce HTML output\n";
    std::cout << "  -d <level>  enable a debug level, such as (multiple invocations of -d are possible):\n";
    std::cout << "\talias\n";
    std::cout << "\tcite\n";
    // ... truncated for brevity
}

void write_file(const std::string& filename, const std::string& content) {
    if (filename == "-") {
        std::cout << content;
    } else {
        std::ofstream f(filename);
        if (!f.is_open()) {
            std::cerr << "Error: Could not open " << filename << " for writing\n";
            return;
        }
        f << content;
        f.close();
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "error: Doxyfile not found and no input file specified!\n";
        print_help();
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];

        if (arg == "-v") {
            print_version();
            return 0;
        } else if (arg == "-V") {
            print_extended_version();
            return 0;
        } else if (arg == "-h" || arg == "-?") {
            print_help();
            return 0;
        } else if (arg == "-d") {
            print_debug_help();
            return 0;
        } else if (arg == "-g") {
            std::string config_name = "Doxyfile";
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                config_name = argv[++i];
            }
            write_file(config_name, templates::CONFIG_TEMPLATE);
            if (config_name != "-") {
                std::cout << "\nConfiguration file '" << config_name << "' created.\n";
                std::cout << "\nNow edit the configuration file and enter\n\n";
                std::cout << "  doxygen " << config_name << "\n\n";
                std::cout << "to generate the documentation for your project\n\n";
            }
            return 0;
        } else if (arg == "-u") {
            std::string config_name = "Doxyfile";
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                config_name = argv[++i];
            }
            write_file(config_name, templates::CONFIG_TEMPLATE);
            if (config_name != "-") {
                std::cout << "\nConfiguration file '" << config_name << "' updated.\n\n";
            }
            return 0;
        } else if (arg == "-l") {
            std::string layout_name = "DoxygenLayout.xml";
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                layout_name = argv[++i];
            }
            write_file(layout_name, templates::LAYOUT_TEMPLATE);
            return 0;
        } else if (arg == "-w") {
            if (i + 1 >= argc) {
                std::cerr << "Error: -w requires arguments\n";
                return 1;
            }
            std::string type = argv[++i];

            if (type == "rtf") {
                if (i + 1 >= argc) {
                    std::cerr << "Error: rtf requires filename\n";
                    return 1;
                }
                write_file(argv[++i], templates::RTF_STYLE_TEMPLATE);
            } else if (type == "html") {
                if (i + 3 >= argc) {
                    std::cerr << "Error: html requires 3+ filenames\n";
                    return 1;
                }
                write_file(argv[++i], templates::HTML_HEADER_TEMPLATE);
                write_file(argv[++i], templates::HTML_FOOTER_TEMPLATE);
                write_file(argv[++i], templates::CSS_TEMPLATE);
            } else if (type == "latex") {
                if (i + 3 >= argc) {
                    std::cerr << "Error: latex requires 3+ filenames\n";
                    return 1;
                }
                write_file(argv[++i], templates::TEX_HEADER_TEMPLATE);
                write_file(argv[++i], templates::TEX_FOOTER_TEMPLATE);
                write_file(argv[++i], templates::TEX_STYLE_TEMPLATE);
            }
            return 0;
        } else if (arg == "-e") {
            if (i + 1 >= argc) {
                std::cerr << "Error: -e requires arguments\n";
                return 1;
            }
            std::string type = argv[++i];
            if (type == "rtf") {
                if (i + 1 >= argc) {
                    std::cerr << "Error: -e rtf requires filename\n";
                    return 1;
                }
                write_file(argv[++i], templates::RTF_EXT_TEMPLATE);
            }
            return 0;
        } else if (arg == "-f") {
            if (i + 1 >= argc) {
                std::cerr << "Error: -f requires type\n";
                return 1;
            }
            std::string type = argv[++i];
            if (type == "emoji") {
                if (i + 1 >= argc) {
                    std::cerr << "Error: -f emoji requires filename\n";
                    return 1;
                }
                write_file(argv[++i], templates::EMOJI_LIST);
            }
            return 0;
        } else if (arg == "-x") {
            // TODO: Implement config comparison
            std::string config_name = "Doxyfile";
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                config_name = argv[++i];
            }
            std::cout << "# Difference with default Doxyfile " << VERSION << " (" << GIT_HASH << ")\n";
            return 0;
        } else if (arg == "-x_noenv") {
            // TODO: Implement config comparison without env
            std::string config_name = "Doxyfile";
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                config_name = argv[++i];
            }
            std::cout << "# Difference with default Doxyfile " << VERSION << " (" << GIT_HASH << ")\n";
            return 0;
        } else if (arg[0] == '-') {
            std::cerr << "error: Unknown option \"" << arg << "\"\n";
            print_help();
            return 1;
        }
    }

    return 0;
}
